using namespace std;

bool isBinaryPalindrome(int x) {
    int rev = 0, temp = x;

    while (temp > 0) {

        // Append LSB to rev
        rev = (rev << 1) | (temp & 1); 

        // Shift temp right
        temp >>= 1; 
    }

    return x == rev;
}

